from time import sleep

from ute_common_abstract_core.exceptions import InvalidConfigurationContent
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ute_ue.exceptions import DataTransferVerificationFailure, UeProcedureError
from ta_ue_plugin_qualcomm.ue.qualcomm.data_transfer.data_transfer_factory import data_transfer_factory
import ute_common_abstract_core.logger as core_logging


class QualcommDataTransfer(LteDataTransfer):
    """Object responsible for managing Qualcomm data transfer."""

    def __init__(self, name, dt_definition, configuration, qualcomm_ue, logger_name='ute_ue'):
        """

        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param qualcomm_ue:
        """
        configuration['ue_logger_name'] = logger_name
        super(QualcommDataTransfer, self).__init__(name, dt_definition, configuration)
        self.logger_name = 'ute_ue.ue.{}_{}.debug'.format(qualcomm_ue.name, self.name)
        self.logger = core_logging.create_logger(self.logger_name, 'ue.{}_{}.debug.log'.format(qualcomm_ue.name, self.name))
        self.logger.propagate = False

        self.logger.info('Creating "{}" instance of QualcommDataTransfer'.format(self.name))
        self.ue = qualcomm_ue
        self._statistics = {}
        try:
            dt_config = configuration['CONSTRUCTOR_PARAMETERS']['configuration']['data_transfer']
            self.sender, self.receiver = data_transfer_factory(dt_config, qualcomm_ue, self.name, dt_definition)
        except KeyError as e:
            raise InvalidConfigurationContent(
                "Configuration is not valid for data transfer. "
                "Qualcomm UE: %s. Expected keyword: %s" % (qualcomm_ue.name, e.args[0]))
        self.logger.info('"{}" instance of QualcommDataTransfer created: '.format(self.name))

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        if self._dt_definition.is_forever_duration() and self._dt_definition.protocol is not 'ICMP':
            raise NotImplementedError('\'forever\' duration is implemented only for ICMP protocol')

        self.receiver.start()
        sleep(4)
        self.sender.start()
        try:
            self.logger.debug("Sender PID: {}".format(self.sender.pid))
        except Exception as e:
            self.logger.info(str(e))
        self.logger.info("Data transmission with name '%s' started." % self.name)

    def release_resources(self):
        """Releases resources on remote UE PC and APP Server"""
        self.logger.info("dt.release_resources call")
        if self._dt_definition.protocol.upper() == 'PING':
            self.get_datagram_loss()
        else:
            self.get_average_throughput()

        if self.sender.is_running():
            self.logger.info("Stopping data transmission on sender...")
            self.sender.stop()
        else:
            self.logger.info("Unable to stop sender thread, because it's not running.")
        sleep(4)
        if self.receiver.is_running():
            self.logger.info("Stopping data transmission on receiver...")
            self.receiver.stop()
        else:
            self.logger.info("Unable to stop receiver thread, because it's not running.")

        self.logger.info("Data transmission with name '%s' stopped." % self.name)

    def stop(self):
        """
        Stops already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        self.logger.info("dt.stop call")
        if self.is_running():
            self.release_resources()
        else:
            self.logger.info("Data transfer already stopped")

    def await_finish(self):
        """
        Waits until this data transfer finish.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        :raises: :py:class:`ute_ue.exceptions.DataTransferCantWaitForeverException`: If this DT has 'forever' duration
        """
        # if self._dt_definition.is_forever_duration():
        #     raise DataTransferCantWaitForeverException("Can't wait forever in DT: %s" % self.name)
        raise NotImplementedError("Keyword Not supported. Use Stop Data Transfer instead")

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        self.logger.debug("sender.is_running(): %s" % self.sender.is_running())
        self.logger.debug("receiver.is_running(): %s" % self.receiver.is_running())
        return True if self.sender.is_running() or self.receiver.is_running() else False

    def check_data_transfer(self):
        """Check if data transfer client and server output is progressing"""
        return self.is_running()

    def get_average_throughput(self, omit=0):
        """
        Method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from 'dt.start()' to 'dt.stop()' if data transfer is already finished

        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :return: value of Average throughput in unit: Kbits/sec
        """
        if omit:
            raise TypeError("Parameter 'omit' is currently not supported by ta_ue_plugin_qualcomm")
        statistics = self._get_statistics()
        self.logger.debug("get_average_throughput stats: %s" % statistics)
        try:
            return statistics['avg'] * 1000.
        except (KeyError, TypeError):
            raise DataTransferVerificationFailure("Unable to get average throughput")

    def get_datagram_loss(self):
        """
        Method for getting datagram loss of data transfer.
        :return: value of datagram loss in unit:
        """
        statistics = self._get_statistics()
        self.logger.info("get_datagram_loss statistics:%s" % statistics)
        try:
            return float(statistics['packet_loss'])
        except (KeyError, TypeError):
            raise DataTransferVerificationFailure("Unable to get datagram loss")

    def reset_statistics(self):
        """
        Method for resetting statistics of data transfer.
        :return: None
        """
        self.receiver.reset_statistics()

    def _get_statistics(self):
        if self.receiver.is_running():
            self._statistics = self.receiver.get_statistics()
        if not isinstance(self._statistics, dict):
            raise UeProcedureError("Unable to get proper data transfer statistics:%s" % self._statistics)
        return self._statistics

